"""Piercy, Russ and Stross: contrasting institutions and a primary Saturn basics check."""
from copy import deepcopy
from best_guess_helpers import current_data,change,write_revision,dated_source,guessed_record,retained_decision,DATE
D=current_data();changes=[];records=[]
sources=[
 dated_source('src-piercy-gildina-classfuture','Woman on the Edge of Time: the opposed future','Wikipedia contributors','https://en.wikipedia.org/wiki/Woman_on_the_Edge_of_Time','Bounded account: New New York has class-separated skyscrapers, bodily commodification, contract sexual service and guards; it is distinct from Mattapoisett.','Secondary synopsis; no whole-city labor census or complete automatic necessities system is supplied.',access='Indexed Gildina and alternative-future passages read'),
 dated_source('src-accelerando-saturn-basics-primary','Accelerando: Saturn’s free basics','Charles Stross','https://govdocs.nebraska.gov/epubs/creativecommons/stross-accelerando.pdf','Indexed page 212: inhabited balloon habitat on Saturn, Economics 1.0 money for goods/services but free food, water, air, power, standard clothing, housing and entertainment.','One bounded primary page; useful voluntary work and local political ownership still need estimates. This is not inner-system Economics 2.0.',kind='primary_text',access='Indexed primary Saturn orientation passage read'),
]
for s in sources:changes.append(change(D,'sources',s))
def add(cid,rid,name,work,period,pop,excluded,desc,values,bounds,bases,facts,assumptions,qualification,regime=3,zero=True,proxy=False,synthetic=False,extra=None):
 refs=D['decisions'][cid]['source_ids']+(extra or [])
 r=guessed_record(cid,rid,name,work,name,['book'],'Named published literary continuity and stated period only',period,pop,excluded,desc,values,bounds,bases,refs,regime,facts,assumptions,qualification,zero=zero,proxy=proxy)
 if synthetic:
  r['scope']['person_proxy_kind']='active_synthetic_persons';r['axis_interpretation']={'nonworking':'Active synthetic-person participation, not a literal human rate.','control':'Independence from organic owners; internal ownership and machine hierarchy remain separate.','literal_human_nonworking':None}
 records.append(r);return r

add('c0140','woman-edge-gildina-zero','Woman on the Edge of Time (Gildina’s corporate future)','Woman on the Edge of Time','The opposed New New York future encountered by Connie','Living biological human residents across the city’s classes','Mattapoisett is a separate possible future; manipulated bodies and contract roles do not imply equal secure access.',
'''Gildina’s future combines class-separated skyscrapers, bodily commodification, contract sexual service and guards. Technical control over bodies coexists with hierarchy and useful or coerced roles. The guarantee best guess is very weak across residents, rather than copied from wealthy upper strata. This zero variant cautiously interprets advanced technical capacity with retained labor, without claiming a complete automatic necessities system from body modification alone.

 Concentrated human corporate and security authority receives control near the elite reference point, with machine operational power inside the interval. A modified body does not give its owner productive sovereignty or make every ruler an AI. The moderate nonworking scenario counts services, care, maintenance, administration, production and imposed roles. Sexual or domestic service remains work where assigned or useful; private intimacy is not automatically a job. The possible-future scope remains distinct from Mattapoisett, and the uncertainty of Connie’s visions is not turned into a canonical census.''',
(.9,.03,.35),([.4,1],[-.75,.45],[.03,.95]),('Class and bodily commodification imply weak equal material security.','Human corporate/security concentration is central with machine discretion possible.','Useful/coerced roles count; bodily modification and class are not participation.'),
['The opposed New New York future has class-separated towers, bodily commodification, contract service and guards.'],['General automation and household rights remain estimates.','The opposed future and Mattapoisett are distinct narrative possibilities.'],'Retain the familiar corporate alternative with its body-technology qualification and possible-future scope explicit.',extra=['src-piercy-gildina-classfuture'])

add('c0141','hesheit-tikva-zero','He, She and It (Tikva’s autonomous information economy)','He, She and It','The functioning free town before a universal conflict outcome','Living human Tikva residents','Corporate indentured citizens and Glop outsiders are different access groups; the defensive cyborg’s real contribution is separately disclosed.',
'''Tikva is a free town in an information economy whose security includes a defensive cyborg. That is a concrete technical-service connection, while ordinary necessities still depend on resident institutions and useful work. The guarantee best guess allows a partial internal floor, qualified by membership, outside threats and unshown household coverage. Free-town status is not itself proof that all food, housing and care arrive automatically.

 Resident human collective and local agency receives positive control weight, unlike a corporate indenture regime. The cyborg’s defensive work does not automatically make him the town’s sovereign provider. The low nonworking scenario counts information work, services, administration, maintenance, care and useful creation. Choosing work freely does not make it leisure, and useful defense remains contribution. The scope does not extend Tikva’s assumed support to excluded Glop residents or corporate enclaves. Broad bounds preserve the limited material evidence while retaining the recognizable decentralized technical alternative.''',
(.15,.7,.2),([-.85,.95],[.15,1],[.02,.85]),('A local floor is plausible but membership and threat limit coverage.','Human free-town agency is central alongside a contributing cyborg.','Information, service, defense and caring roles remain useful work.'),
['The setting distinguishes free towns, corporate indenture and excluded Glop residents; Tikva uses a defensive cyborg.'],['The internal necessities floor and productive substitution depth are estimates.','Defensive artificial-person work is disclosed rather than erased.'],'Retain the famous free-town technical-service model with its limited ordinary provision evidence explicit.',regime=2)

add('c0142','hesheit-yakamura-indentured-zero','He, She and It (Yakamura-Stichen’s indentured enclave)','He, She and It','The functioning corporate dome during Shira’s employment','Living human indentured corporate citizens and resident dependents','Tikva and Glop have different access; one professional’s privileges are not universal human welfare.',
'''Yakamura-Stichen combines a corporate dome and information infrastructure with indentured citizenship and Shira’s interface profession. Engineered habitat and cognitive services therefore coexist with actual work and conditional status. The guarantee best guess is weak because support depends on corporate membership and control rather than an equal secure claim. The zero-variant qualification is technical service and habitation capacity, not a verified end to ordinary productive labor.

 Concentrated human corporate authority receives control near the elite reference point. AI infrastructure does not automatically own its users’ economy or overrule the corporation. The low nonworking scenario counts interface work, administration, production, services, maintenance, care and useful creation. Indenture and occupational rank are not a census of useful participation, and dependents may contribute unpaid care. The point preserves the corporate access population separately from free-town residents and excluded outsiders. Broad uncertainty avoids turning either technological comfort or a single worker’s experience into a complete canonical constitution.''',
(.65,.03,.2),([-.5,.98],[-.7,.45],[.02,.85]),('Corporate membership and indenture make support conditional.','Human corporate owners concentrate authority despite AI infrastructure.','Professional, service and caring roles count; indenture status is not participation.'),
['Yakamura-Stichen has a dome, corporate information systems, indentured citizenship and Shira’s interface profession.'],['Wider household guarantees and automation depth remain uncertain.','Tikva and excluded Glop residents are not assigned corporate rights.'],'Retain the materially different corporate technical enclave with its work dependence explicit.')

add('c0144','female-man-jael-zero','The Female Man (Jael’s segregated technological future)','The Female Man','The functioning segregated future around Jael’s labor-trade relationships','Living human residents of the opposed social orders','Whileaway is a separate continuity; a robot companion is not proof of complete automatic household production.',
'''Jael’s future combines robot companionship, enforced work and labor trade between societies. Its technical service capacity coexists with bodily hierarchy and real useful or imposed roles. The guarantee best guess is weak across residents, while the degree of automatic necessities remains unusually uncertain. This zero variant does not infer a whole machine-funded economy from one companion or import Whileaway’s different institutions.

 Concentrated human political and private authority receives control near the elite reference point, with more dispersed agency and machine discretion inside a broad interval. A robot partner is not automatically the sovereign owner of productive systems. The low nonworking scenario counts production, services, administration, maintenance, care and assigned labor. Contradictory ideological descriptions of work are kept distinct from actual contribution, and private intimacy is not automatically a job. The selected segregated future stays separate from the novel’s other worlds. Its sparse material evidence is labeled rather than converted into a confident uniform welfare claim.''',
(.8,.1,.25),([-.5,1],[-.8,.7],[.02,.9]),('Enforcement and bodily hierarchy suggest weak common material security.','Human political/private concentration is central with alternatives broad.','Actual useful or assigned work counts; companion presence and ideology are not a census.'),
['The critical account describes work enforcement, inter-society labor trade and Jael’s robot companion.'],['General material automation and internal coverage are low-confidence estimates.','Jael’s future and Whileaway have separate scopes.'],'Retain the familiar technological coercion comparison without extrapolating a companion into universal provision.')

add('c0145','fifthsacredthing-working-commons-zero','The Fifth Sacred Thing (San Francisco’s working ecological commons)','The Fifth Sacred Thing','The functioning collective ecological city','Living human San Francisco residents','Sustainable farming remains real labor; collective provision is not evidence of a verified machine-funded post-work system.',
'''San Francisco combines sustainable local agriculture and collective provision. The material floor is therefore not inferred from wealthy private consumers, but necessary human work remains visible. The guarantee best guess allows strong common access with resource and safety limits. This is a deliberately weakly qualified zero-variant comparison of a future ecological support system, not a claim that the short reference proves extensive robotic production or a deliberate rejection of machines.

 Distributed human resident agency gives strongly positive control weight, with local institutional bottlenecks possible inside the interval. Ecological organization is not automatically an independent AI ruler. The low nonworking scenario counts farming, food distribution, maintenance, care, administration and useful creation. Wage-free or voluntary contribution still counts, while private play does not automatically become a job. The exact technical labor-saving depth remains an editorial uncertainty. This keeps the familiar collective future reviewable without equating sustainability with either universal leisure or unlimited dependable abundance.''',
(-.4,.9,.15),([-.95,.9],[.35,1],[.02,.85]),('Collective local provision permits a strong floor with resource/safety limits.','Distributed human community agency is central.','Actual farming, care and distribution count despite voluntary or wage-free organization.'),
['The reference describes sustainable local agriculture and collective provision.'],['Technical labor-saving depth is uncertain and is not asserted as a canonical robot economy.','The zero-variant qualification is comparative and low confidence.'],'Retain the recognizable working ecological commons with its especially weak automation qualification explicit.',regime=2)

add('c0146','accelerando-early-human-transition','Accelerando (the early human automation transition)','Accelerando','The early human economy before Economics 2.0 dominates the inner system','Living human and active human-derived early-transition residents','Manfred’s patrons are not universal welfare; later Saturnian guarantees and destructive inner-system institutions are separate.',
'''Early venture altruism and developing self-replicating production create a plausible transition before autonomous Economics 2.0 dominates. New technical capacity and shared ideas do not yet give every human secure necessities. The guarantee best guess is weak and conditional because private patrons, contracts and unequal access still matter. The point does not import Saturn’s later free basics into the whole earlier economy.

 Human commercial, civic and distributed technical agency receives positive control weight, with growing autonomous machine influence inside the interval. A useful artificial enterprise is not automatically sovereign over every resident. The moderate nonworking scenario permits routine substitution while counting research, services, administration, maintenance, care and useful creation. Venture altruism is not a population employment statistic, and gifted intellectual property is not proof of free physical housing. Active identities alone form the proxy population. This partial-transition record keeps the early emergence distinct from both later human refuge institutions and the destructive inner-system takeover.''',
(.6,.45,.35),([-.6,.98],[-.8,1],[.03,.95]),('Early technical gifts do not establish universal secure material coverage.','Human distributed/commercial agency coexists with growing machine autonomy.','Useful research, service and care remain; patrons and inventions are not a census.'),
['The narrative includes early venture altruism and self-replicating factory development.'],['The early transition is selected before Economics 2.0 domination.','Household rights and participation are estimates, not copied from later Saturn.'],'Retain the distinct early automation transition with private support separated from universal welfare.',regime=4,zero=False,proxy=True)

add('c0148','accelerando-saturn-free-basics','Accelerando (Saturn’s free-basics refuges)','Accelerando','The functioning Saturnian balloon habitats before their later loss','Active biological human and human-derived Saturnian residents','Inner-system Economics 2.0 has different access; inactive backups and absent refugees are not additional supported people.',
'''Saturn’s inhabited balloon habitats retain Economics 1.0 money while providing food, water, air, power, standard clothing, housing and entertainment free. The guarantee best guess is strong for that concrete local floor, qualified by habitat dependence and the finite period before its later loss. Paid extras do not erase the independent basic support, while basic support does not make every resident idle.

 Human-derived resident institutions receive positive control weight, with powerful technical dependencies and concentrated political interests inside the interval. The hostile inner-system machine economy is not treated as the local government merely because it threatens the habitats. The moderate nonworking scenario counts maintenance, administration, services, research, care and useful creation alongside substantial leisure. Money use and refugee numbers are not employment statistics. Only active identities enter the proxy population. This record is materially distinct from the already-retained human remnant exposed to destructive Economics 2.0, whose security is much weaker.''',
(-.75,.55,.5),([-.98,.45],[-.65,1],[.05,.95]),('Primary free necessities establish a strong local floor, with temporal/habitat limits.','Local human-derived institutions retain agency despite technical and external pressures.','Free basics allow leisure, but useful voluntary and institutional work remains.'),
['The primary Saturn orientation lists free food, water, air, power, standard clothing, housing and entertainment alongside money for other goods.'],['Local effective ownership and participation remain estimates.','Only active resident identities count; inner-system institutions are separate.'],'Retain the directly confirmed free-basics refuge economy distinct from Economics 2.0 exclusion.',regime=2,zero=False,proxy=True,extra=['src-accelerando-saturn-basics-primary'])

add('c0151','saturnchildren-android-hierarchy-zero','Saturn’s Children (the slave-chipped android hierarchy)','Saturn’s Children','The functioning post-human Solar System android order','Active synthetic-person android residents across class groups','Extinct humans and inactive hardware are excluded; artificial workers’ continued labor is not erased.',
'''Humanity is extinct, while android aristo rulers own slave-chipped workers who perform low-status tasks. The relevant material needs are energy, components, embodiment and continued operation for active synthetic persons. The guarantee best guess is very weak across that population because ownership and coercion govern access. Human disappearance is not counted as one hundred percent human leisure.

 Independence from organic owners gives strongly negative control weight, while internal android ownership remains sharply unequal. The coordinate describes that independence rather than equal machine power. The low nonworking scenario counts production, maintenance, services, administration, care and imposed roles, including actual courier work. A slave chip does not make a conscious worker mere equipment, and an aristo’s wealth does not establish a common floor. Inactive bodies and destroyed identities are not leisure citizens. This zero variant preserves the working artificial civilization and its inequalities rather than treating every post-human setting as a comfortable post-work utopia.''',
(.95,-.98,.2),([.5,1],[-1,-.7],[.02,.9]),('Slave ownership and chips make equal secure support extremely weak.','Androids are independent of organic masters but unequal among themselves.','Active synthetic workers retain useful and imposed roles; extinct humans are excluded.'),
['After human extinction, android aristos rule slave-chipped workers; Freya undertakes courier work.'],['Active android persons provide the explicit material proxy.','Internal resource coverage and participation are estimates.'],'Retain the famous unequal robot civilization with actual work and no extinction-to-leisure inference.',regime=6,proxy=True,synthetic=True)

add('c0152','neptunesbrood-metahuman-credit-zero','Neptune’s Brood (the metahuman credit economy)','Neptune’s Brood','The functioning interstellar metahuman finance and colony order','Active synthetic-person metahuman residents descended from robots','Extinct biological humans, inactive backups and slow-money balances are not additional persons or nonworkers.',
'''Robot-descended metahumans organize interstellar life through credit and finance. Their artificial continuation does not remove resource costs or useful labor, and the guarantee best guess is weak because access remains institutionally and financially mediated. Biological human extinction is not a welfare achievement. Energy, components, new bodies and colony infrastructure form the explicit synthetic-person material comparison.

 Independence from organic owners gives strongly negative control weight, while creditor power and unequal internal ownership remain separate. A market among artificial people is not equal collective command over production. The modest nonworking scenario counts finance, construction, navigation, administration, maintenance, care and useful creation. Long communication times, monetary units and copied hardware are not a population labor statistic. Only active identities count, without multiplying dormant backups. The zero variant retains the recognizable working metahuman economy rather than assuming credit technology or post-biological bodies establish universal leisure and secure necessities.''',
(.8,-.95,.25),([-.5,.98],[-1,-.55],[.02,.95]),('Credit-mediated embodiment and resources suggest weak universal coverage.','Synthetic independence coexists with concentrated creditors and owners.','Useful financial, productive and caring roles remain; monetary time is not participation.'),
['Metahumans descend from robots after biological human extinction, in an interstellar credit-centered economy.'],['Energy/components and active embodiment are the explicit material proxy.','Internal support and useful-work participation remain broad estimates.'],'Retain the famous synthetic finance economy with active identities and real work explicit.',regime=6,proxy=True,synthetic=True)

add('c0156','ironsunrise-remastered-zero','Iron Sunrise (the ReMastered order)','Iron Sunrise','The published ReMastered society during its conflict with other worlds','Living human and active human-derived ReMastered residents','The author’s unwritten third-book plans are excluded; military ideology alone is not asserted to prove automatic universal provision.',
'''The ReMastered form an ideological and military faction in conflict with independent worlds and the Eschaton. The record keeps that published society distinct from mechanisms proposed for an unwritten sequel. The guarantee best guess is very weak because concentrated coercive authority does not establish equal necessities. Technical productive capacity is a low-confidence contextual qualification, not a claim that military power proves all household labor is already automatic.

 Human-derived institutional command receives control near the elite reference point, with a strongly machine-mediated interpretation inside the wide interval. Opposition to the Eschaton does not itself settle the faction’s internal ownership. The low nonworking scenario counts production, administration, services, maintenance, care and assigned military work. Ideology and augmentation are not employment statistics, and inactive minds are not leisure residents. This zero variant preserves a recognizable technological coercion model while keeping its sparse ordinary material detail and uncertain controller structure explicit rather than inventing a final post-war constitution.''',
(.95,.03,.2),([.4,1],[-1,.45],[.02,.9]),('Coercive factional authority suggests very weak equal secure access.','Human-derived institutional concentration is central with machine mediation uncertain.','Useful and assigned work remains; ideological identity and inactive minds are not participation.'),
['The published narrative concerns independent worlds, Eschaton constraints and the ReMastered conflict.','The author separately describes plans for an unwritten later book.'],['General material automation and controller structure are uncertain.','Unwritten mechanisms are not treated as implemented canon.'],'Retain the published technological faction with weak material qualification and sequel limits explicit.',proxy=True)

cid='c0155';d=deepcopy(D['decisions'][cid]);desc='''The Eschaton imposes causality constraints across independent human worlds, but that intervention does not give all of them one production and distribution system. The identified mechanism is external protection and coercive rule enforcement, not a single shared necessities economy. This receives a completed comparison while specific worlds and factions remain separately scoped in the database.

 The guarantee point is mixed across heterogeneous residents, and strongly negative control records the external machine constraint by analogy rather than ownership of every local productive asset. A modest nonworking scenario counts possible leisure alongside production, services, administration, care and useful creation. It is not a canonical galaxy-wide statistic. Protecting a timeline does not automatically supply food or shelter, and independent worlds can have different labor dependence. The case stays outside the society count for its cross-society constraint scope, not because an exact household law or fictional employment census could not be found.'''
ca=dict(name='Iron Sunrise (Eschaton constraints across human worlds)',media=['book'],scope='Cross-society causality enforcement over independent human worlds, not one common resource institution',axis=dict(guarantees=.3,control=-.8,nonworking=.3),intervals=dict(guarantees=[-.95,1],control=[-1,.85],nonworking=[0,.98]),confidence='low',canon_facts=['The Eschaton imposes causality constraints while human worlds retain distinct institutions.'],editorial_assumptions=['Constraint power is not universal ownership or material provision.','Coordinates are cross-society analogies rather than a canonical common census.'],source_ids=d['source_ids'],counted_toward_goal=False)
d.update(status='boundary_case',current_policy_review=True,reassessed_on=DATE,assessment_mode='best_guess',reason='Completed cross-society constraint comparison; not one shared automated recipient economy.',analysis=desc,comparison_assessment=ca,follow_up='Completed current-policy mechanism comparison; no deep reading required.');changes.append(change(D,'decisions',d))
for r in records:changes.extend([change(D,'societies',r),change(D,'decisions',retained_decision(r,r['qualification_basis']))])
assert len(records)==10,len(records)
write_revision(36,changes,'Ten Piercy/Russ/Stross societies retained. Saturn free basics gain direct primary confirmation and remain separate from inner-system Economics 2.0. Android and metahuman work is explicit, Tikva differs from corporate indenture, and unwritten ReMastered plans are excluded. Eschaton cross-world constraints receive a completed separate comparison.')
